var CP_BASE = {t: "Basics", req: ["issue", "customer", "owner", "due"], f: [{k: "issue", l: "Problem / complaint", ty: "ta"}, {k: "customer", l: "Customer", list: 1}, {k: "ytm", l: "YTM / PO / lot"}, {k: "source", l: "Source", ty: "sel", opts: CP_SRC}, {k: "ref", l: "Ref (inspection / complaint no.)"}, {k: "date", l: "Date", ty: "date"}, {k: "owner", l: "Owner (who does it)", int: 1}, {k: "dept", l: "Dept / line"}, {k: "due", l: "Due date", ty: "date"}, {k: "photos", l: "Photos", ty: "ph"}]};
var CP_CLOSE = {t: "Summary · effectiveness · sign", req: ["sRoot", "sAction"], f: [{k: "sRoot", l: "Summary · root cause (1 line)"}, {k: "sAction", l: "Summary · action (1 line)"}, {k: "sResult", l: "Summary · result (1 line)"}, {k: "eff", l: "Effectiveness — next 3 lots", ty: "tbl", fixed: 3, cols: [["lot", "Lot / date", 1.5], ["r", "Result", 1, ["Pending", "Pass", "Fail"]]]}, {k: "status", l: "Status", ty: "sel", opts: CP_ST}, {k: "signers", l: "Sign by (in order)", ty: "sign"}]};
function cpSteps(m){ return [CP_BASE].concat((CPM[m] || CPM.basic).s, [CP_CLOSE]); }
function cpSug(x){ var s = (x.source || "") + " " + (x.issue || ""); return /complaint|audit/i.test(s) ? "8d" : /risk|process/i.test(s) ? "fmea" : /fail/i.test(s) ? "8d" : "5why"; }
function cpNo(id, d){ return "CA-" + String(d || ymd(new Date())).replace(/-/g, "").slice(2) + "-" + String(id || "NEW").slice(-4).toUpperCase(); }
function cpNE(v){ if(v == null) return false; if(Array.isArray(v)) return v.some(function(r){ return typeof r === "object" ? Object.keys(r).some(function(k){ return k !== "id" && String(r[k] || "").trim(); }) : String(r || "").trim(); }); if(typeof v === "object") return Object.keys(v).some(function(k){ return cpNE(v[k]); }); return String(v).trim() !== ""; }
function cpMissing(x){ return cpSteps(x.method).filter(function(s){ return (s.req || []).some(function(k){ return !cpNE(x[k]); }); }).map(function(s){ return s.t; }); }
function cpProg(x){ var S = cpSteps(x.method), d = S.filter(function(s){ return !(s.req || []).some(function(k){ return !cpNE(x[k]); }); }).length; return Math.round(d * 100 / S.length); }
function cpOver(x){ return x.status !== "Closed" && x.due && x.due < ymd(new Date()); }
function cpDefSign(){ return [{role: "Owner"}, {role: "QA Manager"}, {role: "DGM QA"}, {role: "SGM"}]; }
function cpNew(m, base){ var v = JSON.parse(JSON.stringify(base || {})); v.method = m; v.date = v.date || ymd(new Date()); v.status = v.status || "Open"; v.source = v.source || "Buyer complaint"; v.signers = v.signers || cpDefSign(); v.eff = v.eff || [{lot: "", r: "Pending"}, {lot: "", r: "Pending"}, {lot: "", r: "Pending"}];
  cpSteps(m).forEach(function(s){ s.f.forEach(function(f){ if(v[f.k] != null) return; if(f.ty === "tbl") v[f.k] = [{}]; else if(f.ty === "list") v[f.k] = new Array(f.min || 3).fill(""); else if(f.ty === "fish"){ v[f.k] = {}; CP_CATS.forEach(function(c){ v[f.k][c] = [{t: "", v: false}]; }); } else if(f.ty === "ph") v[f.k] = []; }); }); return v; }
function cpAuto(x){ var top = function(L, k){ return ((L || []).filter(function(r){ return String(r[k] || "").trim(); })[0] || {})[k] || ""; }, m = x.method, R = "", A = "", Z = "";
  if(m === "8d"){ R = x.occ; A = x.corr; Z = x.ver; } else if(m === "5why"){ R = (x.whys || []).filter(function(w){ return String(w).trim(); }).pop(); A = top(x.acts, "what"); }
  else if(m === "fish"){ var c = []; CP_CATS.forEach(function(k){ ((x.fish || {})[k] || []).forEach(function(r){ if(r.v && r.t) c.push(r.t); }); }); R = c.join(" · "); A = top(x.acts, "what"); }
  else if(m === "pdca"){ R = x.cause; A = x.plan; Z = x.chk; } else if(m === "a3"){ R = String(x.rca || "").split("\n")[0]; A = top(x.acts, "what"); Z = x.target; }
  else if(m === "fmea"){ var f = (x.fm || []).map(function(r){ return {r: r, n: (+r.s || 0) * (+r.o || 0) * (+r.d || 0)}; }).sort(function(a, b){ return b.n - a.n; })[0]; if(f && f.n){ R = f.r.mode + " (RPN " + f.n + ")"; A = f.r.act; } }
  else { R = x.root; A = x.action; }
  var e = (x.eff || []).filter(function(r){ return r.r && r.r !== "Pending"; }); if(!Z && e.length) Z = e.map(function(r){ return r.r; }).join(" · ");
  return {r: String(R || "").slice(0, 160), a: String(A || "").slice(0, 160), z: String(Z || "").slice(0, 160)}; }
function cpPhotos(x){ var a = []; cpSteps(x.method).forEach(function(s){ s.f.forEach(function(f){ if(f.ty === "ph") (x[f.k] || []).forEach(function(p){ a.push(p); }); }); }); return a; }
function cpUrls(x){ var U = {}, P = cpPhotos(x).filter(function(p){ return p.id; }); if(!P.length || !window.YQCHAT) return Promise.resolve(U); return Promise.all(P.map(function(p){ return YQCHAT.fileUrl(p.id).then(function(u){ U[p.id] = u; }).catch(function(){}); })).then(function(){ return U; }); }
