  B.innerHTML = (justSent ? '<div class="ycpSub" style="text-align:center;margin-bottom:8px;color:#2f7a14;font-weight:800">✓ Report sent</div>' : '') + '<div id="yqRrP">Loading…</div><div class="rrBar"><button id="yqRrB">‹ All reports</button><button id="yqRrPdf">⬇ PDF</button>' + (canEd ? '<button id="yqRrE">✎ Edit</button>' : '') + '</div>';
